def _save(path, rows) -> str:
    wb = openpyxl.Workbook()
    ws = wb.active
    for r in rows:
        ws.append(r)
    wb.save(path)
    return str(path)


def _statement(title, body, closing):
    return [[title], ["제 2(당)기 %s" % closing[0]], ["제 1(전)기 %s" % closing[1]], ["회사명 : 합성테스트(주)", N, N, N, "(단위 : 원)"],
            ["과        목", "제 2(당)기", N, "제 1(전)기", N], [N, "금액", N, "금액", N]] + [list(r) for r in body]


def write_douzone(folder, key: str = "2026", *, bs=BS, pl=PL, slips=SLIPS, book=BOOK) -> str:
    """더존(위하고) 양식 - 재무상태표 · 손익계산서 · 분개장(+ 계정과목 목록)."""
    _save(folder / ("재무상태표_합성_%s.xlsx" % key), _statement("재 무 상 태 표", bs, ("2026년 12월 31일 현재", "2025년 12월 31일 현재")))
    _save(folder / ("손익계산서_합성_%s.xlsx" % key),
          _statement("손 익 계 산 서", pl, ("2026년 01월 01일부터 2026년 12월 31일까지", "2025년 01월 01일부터 2025년 12월 31일까지")))
    rows = [["분 개 장"], ["일자", "번호", "계정코드", "계정과목", "적요", "차변", "대변", "구분", "거래처코드", "거래처명"]]
    for md, no, lines in slips:
        for code, name, dr, cr in lines:
            rows.append([md, no, code, name, "합성 전표", dr or N, cr or N, "차변" if dr else "대변", "00101", "합성거래처"])
    _save(folder / ("분개장_합성_%s.xlsx" % key), rows)
    if book:
        _save(folder / "계정과목_합성.xlsx", [["코드", "계정과목"]] + [[str(c), n] for c, n in book])
    return str(folder)


def write_semusarang(folder, key: str = "2026") -> str:
    """세무사랑 데이터 내보내기 양식 - 제목 줄 없이 머리 두 줄, 번호는 이름 앞(① 당좌자산), 빈 금액은 0."""
    def flat(body, total=None):
        head = [["과목", "제 2(당)기 2026년1월1일 ~ 2026년12월31일", N, "제 1(전)기 2025년1월1일 ~ 2025년12월31일", N],
                ["과목", "금액", "집계금액", "금액", "집계금액"]]
        out = []
        for r in body:
            name = r[0].replace("(1)", "① ").replace("(2)", "② ")
            if total and name == "부채및자본총계":
                name = total
            out.append([name] + [v or 0 for v in r[1:]])
        return head + out
    _save(folder / ("재무상태표_합성_%s.xlsx" % key), flat(BS, "부채와자본총계"))
    _save(folder / ("손익계산서_합성_%s.xlsx" % key), flat(PL))
    rows = [["일자", "번호", "구분", "계정과목", N, "차변", "대변", "적요", "거래처", N],
            [N, N, N, "코드", "계정과목", "차변", "대변", N, "코드", "거래처명"]]
    for md, no, lines in SLIPS:
        for code, name, dr, cr in lines:
            rows.append(["2026-%s" % md.replace("/", "-"), no, "차변" if dr else "대변", "%04d" % code, name, dr, cr, "합성 전표", "101", "합성거래처"])
    _save(folder / ("분개장_합성_%s.xlsx" % key), rows)
    return str(folder)
